from pwn import *
import string

def generate_fibonacci(n):
    fib = [1, 1]
    for i in range(2, n):
        fib.append(fib[i-1] + fib[i-2])
    return fib

def mod26_fibonacci(n):
    return [x % 26 for x in generate_fibonacci(n)]

def create_substitution_key(seq):
    # Create substitution mapping based on Fibonacci sequence mod 26
    alphabet = list(string.ascii_lowercase)
    mapping = {}
    used = set()

    # Map each letter to its position based on Fibonacci sequence
    for i, num in enumerate(seq):
        if i >= len(alphabet):
            break
        while num in used:
            num = (num + 1) % 26
        mapping[alphabet[i]] = alphabet[num]
        used.add(num)

    # Fill in any remaining unmapped letters
    for i, c in enumerate(alphabet):
        if c not in mapping:
            for j in range(26):
                if alphabet[j] not in mapping.values():
                    mapping[c] = alphabet[j]
                    break

    return mapping

def decrypt_with_key(ciphertext, key):
    return ''.join(key[c] if c in key else c for c in ciphertext)

def reverse_key(key):
    return {v: k for k, v in key.items()}

def try_decrypt():
    # Read the encrypted message
    with open('/home/ctfplayer/ctf_files/message', 'r') as f:
        ciphertext = f.read().strip()

    # Generate different sequences
    fib_seq = mod26_fibonacci(26)
    rev_fib_seq = list(reversed(fib_seq))

    # Create substitution keys
    key1 = create_substitution_key(fib_seq)
    key2 = create_substitution_key(rev_fib_seq)
    key3 = reverse_key(key1)
    key4 = reverse_key(key2)

    # Try different decryptions
    decryptions = [
        ("Forward Fibonacci", decrypt_with_key(ciphertext, key1)),
        ("Reverse Fibonacci", decrypt_with_key(ciphertext, key2)),
        ("Inverse Forward Fibonacci", decrypt_with_key(ciphertext, key3)),
        ("Inverse Reverse Fibonacci", decrypt_with_key(ciphertext, key4))
    ]

    # Try submitting each decryption to the server
    conn = remote('crypto.chal.csaw.io', 8000)

    for name, decrypted in decryptions:
        print(f"\nTrying {name}:")
        print(f"Decrypted text: {decrypted}")

        # Send to server
