        response = conn.recvline().decode()
        print(f"Server response: {response}")

        if "flag" in response.lower():
            print("Found flag!")
            return response

    conn.close()
    return None

if __name__ == "__main__":
    result = try_decrypt()
    if result:
        print(f"\nSuccess! Result: {result}")

