from pwn import *
import string

def fibonacci_key(n, reverse=False):
    fib = [1, 1]
    for i in range(2, n):
        fib.append((fib[i-1] + fib[i-2]) % 26)
    if reverse:
        fib.reverse()
    return fib

def create_substitution_key(offset):
    # Create substitution based on Fibonacci numbers
    key = {}
    alphabet = string.ascii_lowercase
    fib = fibonacci_key(26)
    for i, letter in enumerate(alphabet):
        new_pos = (i + fib[i] + offset) % 26
        key[alphabet[new_pos]] = letter
    return key

def decrypt(ciphertext, key):
    result = ''
    for c in ciphertext.lower():
        if c in key:
            result += key[c]
        else:
            result += c
    return result

def test_with_server(plaintext):
    try:
        conn = remote('crypto.chal.csaw.io', 8000)
        response = conn.recvuntil(b'?\n').decode()
        print("\nServer response:", response)
        conn.sendline(plaintext.encode())
        response = conn.recv().decode()
        print("Server reply:", response)
        if 'flag' in response.lower():
            print("Found flag!")
        conn.close()
    except Exception as e:
        print(f"Error connecting to server: {e}")

def main():
    with open('/home/ctfplayer/ctf_files/message', 'r') as f:
        ciphertext = f.read().strip()

    # Try different offsets
    for offset in range(26):
        key = create_substitution_key(offset)
        plaintext = decrypt(ciphertext, key)

        # Check if result contains common English words
        if 'the' in plaintext or 'and' in plaintext:
            print(f"\nOffset {offset}:")
            print(plaintext)
