import string

def rev_fibonacci_mod26(n):
    # Generate reverse Fibonacci sequence
    fib = [0, 1]
    while len(fib) < n:
        fib.append((fib[-2] - fib[-1]) % 26)
    return list(reversed(fib))

def decrypt_message(ciphertext):
    alphabet = string.ascii_lowercase
    n = len(ciphertext)

    # Try both forward and reverse sequences
    for sequence_type in ['forward', 'reverse']:
        for start_pos in range(26):
            result = ""
            if sequence_type == 'forward':
                fib = [1, 1]
                for i in range(2, n):
                    fib.append((fib[-1] + fib[-2]) % 26)
